class Solution:
    def validSubarrays(self, nums, x):
        n = len(nums)
        pre = [0] * (n + 1)
        for i, v in enumerate(nums):
            pre[i + 1] = pre[i] + v
        ans = 0
        for r in range(n):
            for l in range(r + 1):
                s = pre[r + 1] - pre[l]
                if s % 10 == x:
                    t = s
                    while t >= 10:
                        t //= 10
                    if t == x:
                        ans += 1
        return ans

