class Solution {
public:
    int validSubarrays(vector<int>& nums, int x) {
        int n = nums.size();
        vector<long long> pre(n + 1, 0);
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + nums[i];
        long long ans = 0;
        for (int r = 0; r < n; r++)
            for (int l = 0; l <= r; l++) {
                long long s = pre[r + 1] - pre[l];
                if (s % 10 != x) continue;
                long long t = s;
                while (t >= 10) t /= 10;
                if (t == x) ans++;
            }
        return (int)ans;
    }
};

