class Solution {
public:
    int validSubarrays(vector<int>& nums, int x) {
        unordered_map<int, vector<long long>> buckets;
        buckets[0].push_back(0);
        long long P = 0, ans = 0;
        for (int v : nums) {
            P += v;
            auto& lst = buckets[(int)((P - x) % 10)];
            for (long long p = 1; p <= 100000000000000LL; p *= 10) {
                long long lo = (long long)x * p;
                long long hi = (long long)(x + 1) * p - 1;
                long long ql = P - hi, qr = P - lo;
                ans += upper_bound(lst.begin(), lst.end(), qr) - lower_bound(lst.begin(), lst.end(), ql);
            }
            auto& b = buckets[(int)(P % 10)];
            b.insert(upper_bound(b.begin(), b.end(), P), P);
        }
        return (int)ans;
    }
};

