class Solution {
    public int validSubarrays(int[] nums, int x) {
        Map<Integer, List<Long>> buckets = new HashMap<>();
        buckets.computeIfAbsent(0, k -> new ArrayList<>()).add(0L);
        long P = 0, ans = 0;
        for (int v : nums) {
            P += v;
            List<Long> lst = buckets.get((int) ((P - x) % 10));
            if (lst != null)
                for (long p = 1; p <= 100000000000000L; p *= 10) {
                    long lo = (long) x * p, hi = (long) (x + 1) * p - 1;
                    int a = lowerBound(lst, P - hi);
                    int b = lowerBound(lst, P - lo + 1);
                    ans += b - a;
                }
            int key = (int) (P % 10);
            List<Long> bk = buckets.computeIfAbsent(key, k -> new ArrayList<>());
            bk.add(lowerBound(bk, P) >= 0 ? 0L : 0L);
            bk.remove(bk.size() - 1);
            bk.add(lowerBoundInsert(bk, P), P);
        }
        return (int) ans;
    }
    private int lowerBound(List<Long> a, long t) {
        int lo = 0, hi = a.size();
        while (lo < hi) { int m = (lo + hi) >>> 1; if (a.get(m) < t) lo = m + 1; else hi = m; }
        return lo;
    }
    private int lowerBoundInsert(List<Long> a, long t) { return lowerBound(a, t); }
}

