var validSubarrays = function(nums, x) {
    const buckets = Array.from({length: 10}, () => []);
    buckets[0].push(0);
    let P = 0, ans = 0;
    const lb = (a, t) => {
        let lo = 0, hi = a.length;
        while (lo < hi) { const m = (lo + hi) >> 1; if (a[m] < t) lo = m + 1; else hi = m; }
        return lo;
    };
    for (const v of nums) {
        P += v;
        const lst = buckets[(P - x) % 10];
        for (let p = 1; p <= 1e14; p *= 10) {
            const lo = x * p, hi = (x + 1) * p - 1;
            ans += lb(lst, P - lo + 1) - lb(lst, P - hi);
        }
        const b = buckets[P % 10];
        b.splice(lb(b, P), 0, P);
    }
    return ans;
};
